def strip(x): return html.unescape(re.sub(r'<[^>]+>', '', x))
def block(c):
    segs = '<div class="seg"><b class="t">① 定義</b>%s</div><div class="seg s2"><b class="t">② 法條</b>%s</div><div class="seg s3"><b class="t">③ 涵攝</b><ul>%s</ul></div><div class="seg s4"><b class="t">④ 結論</b>%s</div>' % (c['d'], c['l'], ''.join('<li>%s</li>' % x for x in c['s3']), c['s4'])
    full = ''
    for h, body in c['full']:
        full += '<h4>%s</h4>' % h + (''.join('<p>%s</p>' % p for p in body) if isinstance(body, list) else '<p>%s</p>' % body)
    v1 = '<div class="seg "><b class="t">① 定義</b>%s</div><div class="seg s2"><b class="t">② 法條</b>%s</div><div class="seg s3"><b class="t">③ 涵攝</b>%s</div><div class="seg s4"><b class="t">④ 結論</b>%s</div><p class="nt">速寫版由上方完整範文濃縮，未新增法條事實；⚠️待核處同完整版。</p>' % tuple(c['v1'])
    v2 = '<p class="vh">閱卷看這些關鍵詞</p><div class="kwc">%s</div><p class="vh">常見失分點</p><ul class="lose">%s</ul>' % (''.join('<i>%s</i>' % k for k in c['kw']), ''.join('<li>%s</li>' % k for k in c['lose']))
    return ('<details class="it" data-tier="%s" id="%s"><summary><span class="yr t%s">%s</span><span class="nm">%s</span><span class="pr pP">推估</span><span class="chips">%s</span></summary>'
            '<div class="bd"><p class="oq"><b>預擬題目（自編）</b>：%s</p><div class="vtabs"><button type="button" class="vt on" data-v="0">完整四段式</button><button type="button" class="vt" data-v="1">考場速寫版</button><button type="button" class="vt" data-v="2">得分關鍵・失分點</button></div>'
            '<div class="vp" data-v="0"><h4>為什麼列進來</h4><ul>%s</ul>%s<details class="full"><summary>看完整範文</summary>%s</details><p class="nt">%s</p><p class="warn">%s</p></div>'
            '<div class="vp" data-v="1" hidden>%s</div><div class="vp" data-v="2" hidden>%s</div></div></details>') % (
        c['lv'], c['idv'], c['lv'], c['lv'], c['nm'], ''.join('<i>%s</i>' % x for x in c['chips']), c['oq'][len('預擬題目（自編）：'):],
        ''.join('<li>%s</li>' % x for x in c['why']), segs, full, c['nt'], c['warn'], v1, v2), full

